class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

class Solution:
    def oddEvenList(self, head):
        nodes = []
        cur = head
        while cur:
            nodes.append(cur)
            cur = cur.next
        ordered = nodes[0::2] + nodes[1::2]
        dummy = ListNode()
        tail = dummy
        for node in ordered:
            tail.next = node
            tail = tail.next
        tail.next = None
        return dummy.next

